DECLARE @product_counts TABLE (
    category_id INT,
    product_count INT
);

INSERT INTO @product_counts
SELECT category_id, COUNT(*) AS product_count
FROM   production.products
GROUP BY category_id;

CREATE PROCEDURE Sales.CalculateTax
    @subtotal MONEY
AS
BEGIN
    DECLARE @taxRate DECIMAL(5,4) = 0.085;
    DECLARE @total MONEY;

    SET @total = @subtotal + (@subtotal * @taxRate);
    RETURN @total;
END;

CREATE PROCEDURE Sales.GetCustomerOrderCount
    @customerID  INT,
    @orderCount  INT OUTPUT
AS
BEGIN
    SELECT @orderCount = COUNT(*)
    FROM   sales.orders
    WHERE  customer_id = @customerID;
END;

DECLARE @count INT;
EXEC Sales.GetCustomerOrderCount
    @customerID = 42,
    @orderCount = @count OUTPUT;
PRINT 'Order count: ' + CAST(@count AS VARCHAR(10));
